#### Benchmark Code Snippet
```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <chrono>
#include <random>
#include <cmath>

// Custom QuickSort
void custom_quick_sort(double* arr, int low, int high) {
    if (low < high) {
        int pivotIndex = std::partition(arr + low, arr + high + 1, 
            [mid = arr[(low + high) / 2]](double v) { return v < mid; }) - arr;
        custom_quick_sort(arr, low, pivotIndex - 1);
        custom_quick_sort(arr, pivotIndex + 1, high);
    }
}

// Note: This is a simplified custom QuickSort. Real-world hand-written versions 
// often include median-of-three and small-array insertion sort cutoffs. 
// Even with these, std::sort tends to be faster due to library-level optimizations.

double benchmark(std::function<void(double*)> sort_func, std::vector<double>& data) {
    std::vector<double> d = data; // Copy data to avoid modifying original
    auto start = std::chrono::high_resolution_clock::now();
    sort_func(d.data());
    auto end = std::chrono::high_resolution_clock::now();
    return std::chrono::duration<double, std::milli>(end - start).count();
}

int main() {
    const int N = 10000000;
    std::vector<double> data(N);
    std::mt19937 gen(42); // Fixed seed for reproducibility
    std::uniform_real_distribution<double> dist(0.0, 1.0);

    for (int i = 0; i < N; ++i) {
        data[i] = dist(gen);
    }

    // Warm-up
    benchmark([](double* arr) { std::sort(arr, arr + N); }, data);

    double time_std = 0.0;
    double time_custom = 0.0;
    int runs = 5;

    for (int i = 0; i < runs; ++i) {
        time_std += benchmark([](double* arr) { std::sort(arr, arr + N); }, data);
        time_custom += benchmark([](double* arr) { custom_quick_sort(arr, 0, N - 1); }, data);
    }

    std::cout << "std::sort average time: " << time_std / runs << " ms\n";
    std::cout << "Custom QuickSort average time: " << time_custom / runs << " ms\n";

    return 0;
}
